 if(deliver){const c=s.cargo[id];if(!c||!c.units||s.clock>d.deadline)return false;c.units=0;c.revenue=d.payment;if(id==='lenses')s.flags.observatorySupplied=true;s.credits+=d.payment;advance(s,5);log(s,d.title+' delivered: '+d.payment+' cr; '+d.cost+' cr purchase.');}
