/* Record actual purse changes once at public action boundaries. */
(function(){const M=window.VoyageModel;
function receipt(s,key,args){const P=window.VoyagePorts,id=args[0];if(key==='freight')return P.orders(s)[id].title+(args[1]?' · Delivery payment':' · Purchase');if(key==='trade')return 'Gold '+(id==='buy'?'bought':'sold')+' · '+args[1]+' g';if(key==='discover')return P.encounter(s,id).title;if(key==='meeting')return P.waterMeetings[id].title;if(key==='dock')return 'Yumi’s Metro arrival';if(id==='meal')return P.meals[s.docked].name;if(id==='breakfast')return P.breakfast[s.docked].name;if(id.startsWith('letter-')&&s.letterJob)return P.letterJobs[s.letterJob.id].title;return ({fuel:'Tank refill',tow:'Harbour tug',engine:'Engine tuning',hold:'Cargo racks','deliver-tea':'Mei’s tea · Courier payment','lamp-deliver':'Lighthouse kit · Courier payment',salvage:'Signal-light salvage','constellation-tea':'Supper roasted tea','constellation-ginger':'Supper ginger biscuits','market-collect':'Market evening supplies','market-tea':'Market evening tea','festival-rice':'Festival rice basket','festival-citrus':'Festival citrus','festival-tea':'Festival citrus tea','festival-bun':'Festival sesame bun','festival-celebrate':'Festival celebration'})[id]||'Harbour payment';}
const category=id=>id==='fuel'?'fuel':id==='tow'?'recovery':['engine','hold'].includes(id)?'upgrades':id.startsWith('letter-')?'letters':id.startsWith('festival-')?'festival':id.startsWith('market-')?'festival':['meal','breakfast','constellation-tea','constellation-ginger'].includes(id)?'food':id==='salvage'?'discoveries':'courier';
for(const key of ['action','freight','trade','discover','meeting','dock']){const original=M[key];M[key]=function(s,...args){const before=s.credits,legacy=!s.ledger?{cash:s.credits,gold:s.gold.reduce((n,l)=>n+l.grams*l.cost,0),grams:window.NeonMarket.lots.total(s.gold),clock:s.clock}:null,result=original(s,...args);if(result){if(!s.ledger&&legacy){M.hydrate(s);Object.assign(s.ledger,{openingCash:legacy.cash,openingGoldCost:legacy.gold,openingGoldGrams:legacy.grams,since:legacy.clock});}const id=args[0],cat=key==='action'?category(id):key==='freight'?'cargo':key==='trade'?'gold':key==='discover'?(id==='flowers'?'keepsakes':id==='pontoon'?'food':'discoveries'):key==='meeting'?(id==='trader'&&args[1]==='buy'?'gold':'discoveries'):'courier';M.transaction(s,cat,s.credits-before,receipt(s,key,args));if(key==='freight'&&s.plannedOrders){const pending=s.plannedOrders.filter(id=>!s.cargo[id]||s.cargo[id].units),p=pending.length===2?M.combinedPlan(s,pending):null;s.plannedNext=p?p.legs[0].quay:pending.length?(s.cargo[pending[0]]?.units?window.VoyagePorts.orders(s)[pending[0]].to:window.VoyagePorts.orders(s)[pending[0]].from):'bar';}}return result;};}
})();
